import{_ as o,o as t,c as l,a3 as a}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"1.1 那我问你，什么是阻塞生产","description":"","frontmatter":{"translationSource":{"title":"1.1 那我问你，什么是阻塞生产","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}]]},"headers":[],"relativePath":"zh/1-1-so-tell-me-what-is-production-controlled-by-blocking.md","filePath":"zh/page-quUTb9JSv879txqKEKI0BS.md"}'),n={name:"zh/1-1-so-tell-me-what-is-production-controlled-by-blocking.md"};function s(r,e,i,c,p,d){return t(),l("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-1-那我问你-什么是阻塞生产" aria-hidden="true"></span><h1 id="_1-1-那我问你-什么是阻塞生产" tabindex="-1">1.1 那我问你，什么是阻塞生产 <a class="header-anchor" href="#_1-1-那我问你-什么是阻塞生产" aria-label="Permalink to &quot;1\\.1 那我问你，什么是阻塞生产&quot;">​</a></h1><blockquote><p>源页面 ID：<code>quUTb9JSv879txqKEKI0BS</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>在终末地工业的智能生产领域，由于缺少智能化的原件（例如判断库存达到某个值时，控制阀门打开），目前应用较为广泛的可能仅有<span class="mark-red"><strong>时钟信号、阻塞信号</strong></span>。本教程主要探讨<span class="mark-red"><strong>阻塞信号</strong></span>在智能生产中的应用。</p><blockquote><p>利用时钟信号也能做出很神奇的产线，比如本人曾使用时钟信号实现单烘炉重息壤生产<a href="/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals">基于时钟信号的单烘炉重息壤方案</a>，本页面下半部分的信号控制也有相关内容，也欢迎其他群友在此处引用相关成果。</p><p><a href="/endfield-skydoc/zh/producing-xircon-effluent-in-a-single-reactor-crucible">单个反应池生产壤晶废液</a></p></blockquote><p>正如传送带-分流汇流系统中，流通到阻塞的状态变化会引起流量的<u>重分配</u>（参考<a href="/endfield-skydoc/zh/flow-theory-for-idealized-logistics-systems">理想系统的流量理论</a>，<a href="/endfield-skydoc/zh/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 从阻塞流理论基石上建起阻塞生产学的大厦（缓更）</a>），<strong>生产流程中发生的阻塞也会引起流量的重分配，进而导致生产情况发生变化</strong>。我们可以利用这一特性，实现<strong>生产方案的智能切换</strong>，达到多种进阶的生产目的。</p><blockquote><p>所谓智能切换，指的是产线能在不需要玩家手动干预（如调整设备摆放、状态）的条件下，根据产线自发产出的信号（阻塞、周期等）改变生产方案。</p></blockquote><blockquote><p>本质上，这样的生产形式一定程度上等价于阻塞图的流量求解的数学问题。但是相较于阻塞流理论，阻塞生产进一步加入了机器的要素，使得物品流可以发生变化，与实际应用更紧密相连，同时也带来了很多新的问题。</p></blockquote><p>多种具有实际生产意义的信号，都可归结为某种特定场景下的阻塞信号，例如：</p><ol><li><p><span class="mark-purple">机器满速或达到预定速度生产 → 机器原料缓存阻塞（除原料供给速度=生产速度的临界情形外）</span></p></li><li><p><span class="mark-purple">产物仓储已满 → 生产该产物机器的输出缓存阻塞，连带着输入缓存也阻塞</span></p></li><li><p><span class="mark-purple">流量达到6/m → 设置限速6的准入口，形成阻塞</span></p></li><li><p><span class="mark-purple">液气机反馈中，仅当原料液体充足时，才供应液化息壤 → 原料液体阻塞液化息壤的循环回路，让液化息壤进入液气机供给路线</span></p></li></ol><p>由此可见，我们可以根据实际的生产需求，有意地构建可能形成阻塞的结构，利用不同阻塞状态下流量产生的变化来达成智能生产的目的。阻塞生产原理所要探讨的内容就包括：<strong>如何构建这些结构，这些结构在何种条件下会形成阻塞，该阻塞会导致产线流量发生怎样的重分配，是否能达成最终的生产目的</strong>。</p><p>阻塞生产并不是神秘高深的理论，只需要你在原有产线基础上再接着往下多想一步，大家或许已经在各种地方见到过使用过了，相比之下更关键的是如何认识这一现象。</p><blockquote><p>爆仓当然是阻塞的一种表现，所以爆仓时产线会如何发生变化，也是阻塞生产原理所关注的重要内容（爆仓动力学.jpg）</p></blockquote><blockquote><p>如果说初级的产线设计是达到把一定数目或者速率的原料x<em>供给做成一定速率的产品y</em>（即做完后报表图显示正确），f(x*) = y*, 那么本文所讨论的就是更高一层次的产线设计：在前者基础上，探讨在外部环境（如原料供给，或产物堆满）发生变化的情形下，产线的响应是什么，以及如何应用这些产线的响应达到我们想要的更复杂的生产需求。我们需要分析函数f是否对一定范围内的x都能给出正确的y；产线在原料x<em>的供应量发生变化时，y</em>是否能够正确地反映我们想要的结果；或者在y<em>发生变化时，x</em>能否正确发生相应的响应。</p></blockquote><p><a href="/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production">1.2 采用阻塞生产形式有什么好处</a></p></div>',1)])])}const k=o(n,[["render",s]]);export{u as __pageData,k as default};
